const legacyReferences=`<section id="appendix" class="appendix"><div class="section-badge"><span class="badge-num">부록</span>근거와 배포 전 확인</div><h2 class="section-h2">사실과 가정을 구분하는 자료</h2>${table(['주장·자료','근거와 범위'],[['제품·플랫폼 구조','2026.10.05 팀 전략과 실제 콘텐츠 이미지. 실제 화면·활동 도해·예정 연계를 구분.'],['콘텐츠 수','catalogue-scale-20261005.json: 동화 등록1215·공개362·창작850/19시리즈 당시 기록. 최신 상태·제작 완료·공개를 다시 확인해야 함.'],['미나 제작','20260928-mina02-50-qwen-scenes.md: 01 포함50권500장 삽화 제작·검수·등록. 시간·비용 실측은 별도.'],['부모 리포트','실제 제품에 테스트 데이터를 넣은 캡처. 운영 검증 기록은 제품 동작 근거; 고객 트랙션이나 학습 효과 아님.'],['교원 협업','<a href="https://www.kyowon.co.kr/Media/News_detail?iscont=&nttId=442&searchword=">교원 공식 발표 2020.10.29</a>. 상품 협업과 창업자 진술의 역할·실적을 구분.'],['경쟁시장','<a href="https://monkey.edu.vn/san-pham/vmonkey">VMonkey 공식 소개</a>: 베트남어 이야기·읽기·게임 제공. 시장 공백·경쟁사 노후화 단정 없음.'],['시장 배경','<a href="https://repo.kicce.re.kr/bitstream/2019.oak/5833/2/SP2501.pdf">육아정책연구소·교육부 시험조사 인용: 2024년7–9월 유아 사교육비8,154억원</a> · <a href="https://www.technavio.com/report/early-childhood-education-market-industry-analysis">Technavio: 세계 유아교육2025년3,027.6억달러 추정</a>. 범위·기간 차이와 하드웨어 판매 가능 시장을 구분.'],['확장·개인화','언어별 학습 설계·현지 검수와 지원 필요. 한 책=한 그림체·한 레벨. 아이의 언어별 근거를 합산해 습득으로 판정하지 않음.']])}<h3>실제 경쟁 비교는 동일한 질문으로 확인합니다.</h3><p>첫 읽기 교육과정 · 이야기와 활동의 실제 대응 · 부모 기록의 근거 · 언어별 학습 설계 · 이용 조건과 가격. 경쟁 서비스도 통합 학습·리포트를 제공하므로 탱고북만 가능하다고 주장하지 않습니다.</p><h3>배포 전 필수 확정</h3><p>대표·팀의 실제 이력과 근무/계약 상태, 최신 공개/완성 자산, 실제 가족 코호트 지표, 교육·생성물 권리·자산 이용 조건, 제작/지원 원가, 국가별 가격 실험, 현금흐름·필요 투자액·투자금 마일스톤.</p><p class="note">작성 기준: 2026.10.10 저장소·작업 기록. 이번 작성은 운영 데이터 변경이나 고객 성과 측정을 수행하지 않았습니다. 이 문서는 투자 논의용 초안이며, 운영 접근 정책을 변경하지 않습니다.</p></section>`;
const references=`<section id="appendix" class="appendix td-source-notes"><div class="section-badge"><span class="badge-num">참고</span>본문 출처</div><details class="v-evidence"><summary>시장·제품·개발 이력의 근거</summary><dl><dt>1장 · 시장</dt><dd><a href="https://repo.kicce.re.kr/bitstream/2019.oak/5923/2/GR2502_2.pdf#page=77" target="_blank" rel="noopener">육아정책연구소 · KICCE 소비실태조사 2025 하권, 55쪽</a> / <a href="https://www.technavio.com/report/early-childhood-education-market-industry-analysis" target="_blank" rel="noopener">Technavio · 세계 유아교육 시장</a>. 국내는 2024년 영유아 1인당 양육비와 교육·보육비입니다. 세계 시장 전망과 아시아 성장 배경은 각각 Technavio 및 <a href="https://www.emergenresearch.com/industry-report/early-childhood-education-market" target="_blank" rel="noopener">Emergen Research</a> 분석이며 범위가 다릅니다.</dd><dt>3~9·11~12장 · 제품·콘텐츠·기술·확장</dt><dd>교구 이미지는 제품 구성·활동 예시, 미션 진행은 화면 구성 예시입니다. 탱고노트는 사용자 제공 2024 제안서와 2026.10.11 설명을 참고해 구성했으며, 노트판의 종이 필기와 학습지 정보를 블루투스로 태블릿에 전달하는 방식입니다. 한글·영어 파닉스는 보유 커리큘럼의 권별 구성과 문자 예시를 보여줍니다. 동화책 표지·창작 시리즈 본문은 보유 자산이며, 거인의 정원 네 가지 독후활동은 실제 서비스 화면입니다. AI 저작도구는 실제 삽화와 예시 원고를 배치한 구성 예시입니다. 추가 블록은 제품 콘셉트, 창작동화와 타임 티코는 보유 자산이며 신규 언어·교구·만화 라인업은 확장 계획입니다. 인식기와 앱 카메라 연결은 구현 기반이며 실기기 성능·아동 사용성 검증은 별도입니다.</dd><dt>14장 · 개발 이력</dt><dd>과거 플레이탱고 IR 및 <a href="https://www.kyowon.co.kr/Media/News_detail?iscont=&nttId=442&searchword=" target="_blank" rel="noopener">교원 공식 발표(2020.10.29)</a>. 과거 제품 이력과 현재 탱고북의 성과를 구분합니다.</dd></dl></details></section>`;
const css=`:root{--ink:#173c37;--muted:#536861;--paper:#f7f5ef;--line:#dce4dd;--accent:#ba503b}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:80px}body{margin:0;background:var(--paper);color:var(--ink);font:18px/1.65 'Malgun Gothic',system-ui,sans-serif}header{padding:16px 24px;background:#173c37;color:white;display:flex;justify-content:space-between;align-items:center;position:sticky;top:0;z-index:5}header small{color:#bed1c8}header button{border:1px solid #8baa9d;background:transparent;color:white;padding:8px 12px;border-radius:7px;margin-left:5px;cursor:pointer}main{max-width:1320px;margin:auto;padding:0 40px}section{padding:56px 0 48px;min-height:720px;border-bottom:1px solid var(--line)}.section-badge{font-size:13px;letter-spacing:.1em;text-transform:uppercase;display:flex;gap:12px;align-items:center}.badge-num{background:var(--accent);color:white;padding:5px 9px;border-radius:5px}.section-h2{word-break:keep-all;font-size:46px;line-height:1.24;letter-spacing:-.045em;text-align:left;max-width:1050px;margin:22px 0 14px}.section-sub{color:var(--muted);margin-bottom:28px}.split{display:grid;grid-template-columns:1fr 1fr;gap:32px;align-items:start}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin:22px 0}.split .cards{grid-template-columns:1fr}article{background:white;border:1px solid var(--line);border-radius:16px;padding:24px}h3{font-size:23px;line-height:1.4;margin:0 0 12px}p{margin:14px 0}a{color:#276452;text-underline-offset:4px}.lead{font-size:29px;line-height:1.5;letter-spacing:-.02em}.note{background:#eaf0e9;padding:16px 20px;border-radius:10px;color:var(--muted);font-size:15px}.pills{display:flex;flex-wrap:wrap;gap:8px}.pills span{border:1px solid #b5c8b9;border-radius:30px;padding:6px 12px;font-size:14px}.flow{display:flex;align-items:center;justify-content:space-between;gap:15px;margin:24px 0}.flow b{background:white;border:1px solid var(--line);padding:18px;border-radius:12px;text-align:center;flex:1}.flow span{color:var(--accent);font-size:26px}.gallery{display:grid;grid-template-columns:2fr 1fr 1fr;gap:16px;align-items:center}.gallery img{width:100%;max-height:290px;object-fit:contain;background:white;border-radius:14px}.covers{display:flex;gap:18px;justify-content:center;margin:24px 0}.covers img{width:20%;height:220px;object-fit:contain}img{max-width:100%;display:block}.overview{height:410px;width:100%;object-fit:contain}.book{max-height:300px;max-width:100%;margin:auto}figure{margin:0}figure img{height:365px;width:100%;object-fit:contain;background:white;border-radius:14px}figcaption{font-size:13px;color:var(--muted);text-align:center;margin-top:8px}.table-wrap{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:16px}th,td{text-align:left;vertical-align:top;padding:16px;border-bottom:1px solid var(--line)}th{background:#eaf0e9}td:first-child{font-weight:700;width:23%}.formulas{display:grid;grid-template-columns:1fr 1fr;gap:12px;font-size:16px}.formulas p{background:white;padding:16px;border-radius:9px}.appendix{min-height:0}.present section{display:none;min-height:calc(100vh - 70px);border:0}.present section.active{display:block}.present .appendix{display:none}.present main{max-width:1320px}@media(max-width:800px){body{font-size:16px}main{padding:0 20px}section{padding:35px 0;min-height:0}.section-h2{font-size:32px}.split,.cards,.formulas{grid-template-columns:1fr}.flow{flex-direction:column}.flow span{transform:rotate(90deg)}.flow b{width:100%}.overview{height:auto}.gallery{grid-template-columns:1fr 1fr}.gallery img:first-child{grid-column:1/-1}.covers{gap:8px}.covers img{height:150px;width:23%}header small{display:none}td,th{padding:10px}table{min-width:620px}.lead{font-size:25px}}@media print{header{display:none}body{background:white;font-size:12pt}main{padding:0;max-width:none}section,.present section{display:block!important;min-height:0;break-before:page;padding:20px 0;border:0}section:first-child{break-before:auto}.section-h2{font-size:30pt}.section-sub{margin-bottom:15px}.note{font-size:10pt}.overview{height:320px}article{padding:14px}.cards{gap:10px}table{font-size:10pt;min-width:0}td,th{padding:9px}.gallery img{max-height:230px}.covers img{height:170px}figure img{height:300px}.table-wrap{overflow:visible}a{color:inherit}.appendix{display:block!important}}`;
const js=fs.readFileSync(path.join(__dirname,'business-plan-navigation.js'),'utf8');
const html=`<!doctype html>\n<html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>탱고북 투자자용 사업계획서</title><style>${css}</style></head><body><header><select id="chapter-select" aria-label="장 선택">${slides.map(([id,num,cat,title],i)=>`<option value="${i}">${num} · ${title}</option>`).join('')}</select><div><span id="count"></span><button id="prev" aria-label="이전 장">←</button><button id="next" aria-label="다음 장">→</button><button id="mode">발표 모드</button><button id="print">인쇄</button></div></header><main>${slides.map(([id,num,cat,title,sub,body])=>`<section id="${id}" class="doc-page doc-layout-${documentSystem.layoutFor(id)}" data-doc-layout="${documentSystem.layoutFor(id)}"><div class="section-badge"><span class="badge-num">${num}</span>${cat}</div><h2 class="section-h2">${title}</h2><div class="section-sub">${sub}</div>${body}</section>`).join('\n')}${copyedit.prose(references)}</main><script>${js}</script></body></html>\n`;
const simulation = require('./business-plan-simulation-20261011.cjs');
const marketing = require('./business-plan-marketing-20261011.cjs')({img});
const shellJs = `
document.querySelectorAll('[data-learning-language]').forEach(button=>{button.onclick=()=>{document.querySelectorAll('[data-learning-language]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelectorAll('[data-learning-panel]').forEach(panel=>panel.hidden=panel.dataset.learningPanel!==button.dataset.learningLanguage);};});
const tabs=[...document.querySelectorAll('.audience [role="tab"]')];
function switchTab(which,updateHash=true){
 if(!tabs.some(t=>t.dataset.tab===which))which='investor';
 document.body.dataset.audience=which;
 tabs.forEach(t=>{const active=t.dataset.tab===which;t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1;document.getElementById(t.getAttribute('aria-controls')).hidden=!active;});
 if(updateHash){history.replaceState(null,'','#'+which);window.scrollTo({top:0,behavior:'instant'});}
}
tabs.forEach((t,i)=>{t.onclick=()=>switchTab(t.dataset.tab);t.onkeydown=e=>{let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;if(e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();e.stopPropagation();switchTab(tabs[next].dataset.tab);tabs[next].focus();}};});
document.querySelectorAll('[data-open-tab]').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();switchTab(link.dataset.openTab);document.getElementById(link.dataset.openTab+'-tab').focus({preventScroll:true});}));
function selectHashTab(){switchTab(location.hash==='#simulation'?'simulation':/^#marketing(?:-|$)/.test(location.hash)?'marketing':'investor',false);}
selectHashTab();window.addEventListener('hashchange',selectHashTab);
document.querySelector('#marketing-print').onclick=()=>window.print();
`;

const combined = html.replace('<title>탱고북 투자자용 사업계획서</title>','<title>탱고북 사업계획서</title>')
 .replace('</style>',visualPlan.css+'</style>')
 .replace('</style>','#media figure img{height:200px}#media .section-h2{font-size:38px}#media article{padding:20px}#media figcaption{font-size:12px}#media .split .split{gap:12px}#education-market article{padding:32px}#background figure img,#business figure img{height:250px}@media(max-width:800px){#media .section-h2{font-size:30px}#media figure img{height:auto;max-height:260px}}@media print{#media .section-h2{font-size:28pt}#media figure img{height:160px}}</style>')
 .replace('</style>',`.audience{position:sticky;top:0;z-index:30;background:#173c37;color:white;padding:12px 24px;display:flex;align-items:center;gap:12px}.audience b{margin-right:auto}.audience button{font:inherit;font-size:15px;padding:8px 15px;border-radius:8px;border:1px solid #789589;background:transparent;color:white;cursor:pointer}.audience button[aria-selected="true"]{background:#f7f5ef;color:#173c37}.audience small{font-size:12px;color:#c6d9ce}#investor-panel>header{top:64px}[hidden]{display:none!important}@media(max-width:650px){.audience{flex-wrap:wrap;padding:10px 12px}.audience small{display:none}#investor-panel>header{top:64px}header{padding:10px 12px;font-size:13px}}@media print{.audience{display:none}#investor-panel{display:block!important}}</style>`)
 .replace('</style>',editorialCss+simulation.css+marketing.css+'</style>')
 .replace('<body>',`<body><nav class="audience" aria-label="사업계획서 독자"><b>탱고북 사업계획서</b><small>통합 검토본 · 2026.10.11</small><div role="tablist" aria-label="문서 대상"><button role="tab" id="investor-tab" aria-controls="investor-panel" aria-selected="true" data-tab="investor">탱고북 소개서</button><button role="tab" id="simulation-tab" aria-controls="simulation-panel" aria-selected="false" tabindex="-1" data-tab="simulation">매출 시뮬레이션</button><button role="tab" id="marketing-tab" aria-controls="marketing-panel" aria-selected="false" tabindex="-1" data-tab="marketing">판매·마케팅 전략</button></div></nav><div id="investor-panel" role="tabpanel" aria-labelledby="investor-tab">`)
 .replace('</main><script>',`</main></div>${simulation.html}${marketing.html}<script>${shellJs}</script><script>${simulation.js}</script><script>`);
// 정적 서버가 파일을 읽는 동안 Windows의 직접 덮어쓰기가 실패할 수 있다.
// 완성된 임시 파일을 교체해 읽는 쪽에 중간 생성물을 노출하지 않는다.
const outputPath=path.join(root,'packages/client/public/tangobook-business-plan.html');
const temporaryPath=outputPath+'.build-'+process.pid;
fs.writeFileSync(temporaryPath,combined);
for(let attempt=0;;attempt++){
 try{fs.renameSync(temporaryPath,outputPath);break;}
 catch(error){if(attempt>=40||!['EPERM','EBUSY','UNKNOWN'].includes(error.code))throw error;Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0,100);}
}
console.log(`Built one canonical business plan: investor ${slides.length} sections; introduction, simulation and marketing tabs; embedded assets.`);
